<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;use App\Http\Resources\VehicleResource;use App\Models\Location;use App\Models\VehicleCategory;use App\Services\AvailabilityService;use Carbon\Carbon;use Illuminate\Http\Request;
class AvailabilityController extends Controller { public function __construct(private AvailabilityService $service){} public function __invoke(Request $r){$d=$r->validate(['pickup_date'=>'required|date','return_date'=>'required|date','pickup_time'=>'nullable|date_format:H:i','return_time'=>'nullable|date_format:H:i','pickup_location'=>'nullable|string|max:120','category'=>'nullable|string|max:120']);$pickup=Carbon::parse($d['pickup_date'].' '.($d['pickup_time']??'10:00'));$return=Carbon::parse($d['return_date'].' '.($d['return_time']??'10:00'));abort_if($return->lessThanOrEqualTo($pickup),422,'Return date/time must be after pickup date/time.');$locationId=!empty($d['pickup_location'])?Location::where('name',$d['pickup_location'])->orWhere('slug',$d['pickup_location'])->value('id'):null;$categoryId=!empty($d['category'])?VehicleCategory::where('name',$d['category'])->orWhere('slug',$d['category'])->value('id'):null;$vehicles=$this->service->availableVehicles($pickup,$return,$locationId,$categoryId);return response()->json(['data'=>['pickup_at'=>$pickup->toIso8601String(),'return_at'=>$return->toIso8601String(),'vehicles'=>VehicleResource::collection($vehicles)]]);} }
